import hashlib,os,sys,zipfile
p,m,out,archive_sha,member_sha,record_sha,size=sys.argv[1:]
def digest(stream):
    h=hashlib.sha256()
    while True:
        block=stream.read(1048576)
        if not block: break
        h.update(block)
    return h.hexdigest()
with open(p,"rb") as archive:
    if digest(archive)!=archive_sha: sys.exit("archive SHA mismatch")
    archive.seek(0)
    with zipfile.ZipFile(archive) as z:
        infos=z.infolist()
        if len(infos)!=71 or len({i.filename for i in infos})!=71 or sum(i.file_size for i in infos)!=457373801: sys.exit("archive structure mismatch")
        info=z.getinfo(m)
        if info.file_size!=int(size): sys.exit("member size mismatch")
        with z.open(info) as stream:
            if digest(stream)!=member_sha: sys.exit("member SHA mismatch")
        with z.open(info) as stream: line=stream.readline(8388609)
        if len(line)>8388608 or not line.endswith(b"\n") or hashlib.sha256(line).hexdigest()!=record_sha: sys.exit("first record mismatch")
    archive.seek(0)
    if digest(archive)!=archive_sha: sys.exit("archive changed while staging")
fd=os.open(out,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)
with os.fdopen(fd,"wb") as output:
    if output.write(line)!=len(line): sys.exit("short write")
    output.flush(); os.fsync(output.fileno())

